import{OCEAN_CONFIG as u}from"./config.min.js";function s(r,t,e){if(t<=r)return e>=t?1:0;const n=Math.max(0,Math.min(1,(e-r)/(t-r)));return n*n*(3-2*n)}function c(r,t,e){return r+(t-r)*e}export function arcProgress(r,t=u.storm){const e=t.seconds>0?t.seconds:1;return Math.max(0,Math.min(1,r/e))}export function stageAt(r,t=u.storm){const e=t.stages;let n=e[0];for(let o=0;o<e.length;o++)r>=e[o].from&&(n=e[o]);return n}export function stageProgress(r,t=u.storm){const e=t.stages;for(let n=0;n<e.length;n++){const o=e[n].from,a=n+1<e.length?e[n+1].from:t.seconds;if(r>=o&&(r<a||n===e.length-1))return a<=o?1:Math.max(0,Math.min(1,(r-o)/(a-o)))}return 0}export function swellAt(r,t=u.storm){return curveAt(r,t.swell,t)}export function leanAt(r,t=u.storm){return curveAt(r,t.lean,t)}export function surgeAt(r,t=u.storm){return curveAt(r,t.surge,t)}export function curveAt(r,t,e=u.storm){if(!t||t.length===0)return 0;if(t.length===1)return t[0].value;const n=Math.max(0,Math.min(e.seconds,r));if(n<=t[0].at)return t[0].value;const o=t[t.length-1];if(n>=o.at)return o.value;for(let a=1;a<t.length;a++)if(n<=t[a].at){const l=t[a-1],f=t[a];return c(l.value,f.value,s(l.at,f.at,n))}return o.value}export function engulfAt(r,t=u){const e=t.camera.height,n=t.storm.engulfWashMetres;return s(e-n,e+n,r)}export function surfaceAtCamera(r,t=u){const{beach:e,camera:n}=t,o=(n.z-e.shoreZ)*e.slope;return Math.max(o,r)}export function fadeAt(r,t=u.storm){const e=t.seconds-t.fadeSeconds;return s(e,t.seconds,r)}export function stormStateAt(r,t=u,e=null){const n=t.storm,o=surgeAt(r,n),a=e??surfaceAtCamera(o,t);return{seconds:r,progress:arcProgress(r,n),stage:stageAt(r,n).name,swell:swellAt(r,n),lean:leanAt(r,n),surge:o,engulf:engulfAt(a,t),fade:fadeAt(r,n),finished:r>=n.seconds}}
